import pandas as pd,numpy as np,glob
from scipy.signal import lfilter
def lp(u,T):
    a=.001/T;return lfilter([a],[1,-(1-a)],u-u[0])+u[0]
def feats(d,Ts=(.02,.08,.4,3)):
    V=d.voltage_pu.values-d.voltage_pu.values[0];Vs=d.voltage_setpoint_pu.values-d.voltage_pu.values[0]
    th=d.bus_angle_rad.values
    cols=[V,Vs]
    for T in Ts:
        cols+= [lp(V,T),lp(Vs,T)]
    for T in (.02,.1):
        cols.append((th-lp(th,T))/T)
    return np.array(cols).T
def load(split):
    return [pd.read_csv(f) for f in sorted(glob.glob(split+'/*.csv'))]
Tr=load('train');Va=load('val')
for name,col in (('Q','reactive_power_pu'),('P','active_power_pu')):
    X=np.vstack([feats(d)[500::5] for d in Tr]);y=np.concatenate([(d[col].values-d[col].values[0])[500::5] for d in Tr])
    c,*_=np.linalg.lstsq(X,y,rcond=None)
    print(name,c.round(3),np.sqrt(np.mean((X@c-y)**2)),y.std())
    for d in Va:
        Xv=feats(d)[500::5];yv=(d[col].values-d[col].values[0])[500::5]
        print(' val',np.sqrt(np.mean((Xv@c-yv)**2)),yv.std())
